formatDuration(_calendar, components, {formatter, maxTerms, ...options}={}) {
    let hasNegative = false; // Was a negative-value component found?
    const FORMAT_UNITS = Array.from(CalendarData._DURATION_FORMAT_UNITS);
    const durationEntries = iterateEntries(components).reduce((arr, [key, value]) => {
      if ( !CalendarData._DURATION_FORMAT_UNITS.has(key) ) return arr;
      value = Number(components[key]) || 0;
      const rounded = Math.round(value);
      if ( rounded < 0 ) hasNegative = true;
      if ( hasNegative || (rounded < 1) ) return arr;
      arr.push([`${key}s`, rounded]);
      return arr;
    }, []).sort((a, b) => FORMAT_UNITS.indexOf(a[0].slice(0, -1))
      - FORMAT_UNITS.indexOf(b[0].slice(0, -1))).slice(0, maxTerms);
    if ( durationEntries.some(e => !Number.isFinite(e[1])) ) return "∞";
    if ( !durationEntries.length ) durationEntries.push(["seconds", 0]);
    options.style ??= "long";
    formatter ??= new Intl.DurationFormat(game.i18n.lang, options);
    try {
      return formatter.format(Object.fromEntries(durationEntries));
    }
    catch(error) {
      const message = `Unable to format duration with components ${JSON.stringify(components)}`;
      if ( error instanceof RangeError ) {
        console.error(message);
        return "∞";
      }
      else throw new Error(message, {cause: error});
    }
  }
